VALUES ('club_new-york-salmagundi-club-mahjong-club', 'Salmagundi Club Mahjong Club', 'new-york-salmagundi-club-mahjong-club', 'Weekly Thursday morning mahjong at the Salmagundi Club in Greenwich Village. Quote from the club page: "join us for American-style mahjong at Salmagundi!" Players must bring their own official National Mah Jongg League card; RSVP required so enough sets and tables can be prepared.', (SELECT id FROM City WHERE name = 'New York' AND state = 'NY'), 'Salmagundi Club, 47 Fifth Avenue, New York, NY 10003', 'https://salmagundi.org/mahjong-club/', NULL, NULL, NULL, NULL, 1, 0, 1, 1, 0, 0, 10, 'Every Thursday 11:00 AM-1:00 PM; $10 general admission; RSVP required', 'https://salmagundi.org/2026-mahjong-club-05-28/', '2026-11-11', 'ACTIVE')
