VALUES ('club_memphis-memphis-jewish-community-center-mah-jongg-classes', 'Memphis Jewish Community Center (Mah Jongg classes)', 'memphis-memphis-jewish-community-center-mah-jongg-classes', 'Adult Mah Jongg classes at the Memphis JCC. Beginning Mah Jongg with Melanie Mann; Advanced with Vicki Campbell. The JCC''s own page says the advanced class covers Charleston and defensive play and "the new 2026 NMJL card" (quoted from fetched page text; recheck wording). Open to non-members at regular price ($80 regular / $72 members per session block).', (SELECT id FROM City WHERE name = 'Memphis' AND state = 'TN'), 'Memphis Jewish Community Center', 'http://www.jccmemphis.org/adults/adult-classes', NULL, NULL, NULL, NULL, 1, 1, 0, 0, 0, 0, NULL, 'Beginning: Tue or Thu 6:00-8:00pm; Advanced: Tue 2:00-4:00pm. Fall blocks listed on page ended 11/5/2026 (10/6-11/3 and 10/8-11/5); next session dates not published on page.', 'http://www.jccmemphis.org/adults/adult-classes', '2026-11-12', 'ACTIVE')
