VALUES ('club_new-york-congregation-rodeph-sholom-mah-jongg-classes-open-play', 'Congregation Rodeph Sholom — Mah Jongg (classes + open play)', 'new-york-congregation-rodeph-sholom-mah-jongg-classes-open-play', 'Congregation Rodeph Sholom (Upper West Side) offers Mah Jongg classes. Its own event page says: "an introduction to American-style Mah Jongg for the brand-new player or those looking for a refresher." Taught by congregation members on the CRS Mah Jongg Advisory Council; 3 consecutive class days plus a game day; capped at 8 people.', (SELECT id FROM City WHERE name = 'New York' AND state = 'NY'), '7 West 83rd Street, New York, NY 10024', 'https://rodephsholom.org/event/mah-jongg-class-2/', NULL, 'crs@crsnyc.org', NULL, NULL, 1, 1, 0, 0, 0, 0, NULL, 'Free for CRS members; $154 for non-members (2026 page: includes Mah Jongg card). Class days Mon-Wed, alternating 6:30-8:30pm and 10am-12pm. Registration via SimpleTix.', 'https://rodephsholom.org/event/mah-jongg-class-2/2026-01-13/', '2026-11-12', 'ACTIVE')
