VALUES ('club_raleigh-mah-jongg-mondays-cary-regional-library', 'Mah Jongg Mondays (Cary Regional Library)', 'raleigh-mah-jongg-mondays-cary-regional-library', 'Wake County Libraries drop-in program at Cary Regional Library (Cary, NC). Library''s own page says: "Drop-in and play American Mah Jongg every 2nd and 4th Monday, 9:30 to 11 a.m." Players need a basic understanding of American Mah Jongg and a 2026 Mah Jongg card; sets provided; no registration.', (SELECT id FROM City WHERE name = 'Raleigh' AND state = 'NC'), '315 Kildaire Farm Road, Cary, NC 27511', 'https://www.wake.gov/events/mah-jongg-mondays-34', NULL, NULL, NULL, NULL, 0, 0, 1, 1, 0, 1, NULL, 'Every 2nd and 4th Monday 9:30-11:00 a.m.', 'https://www.wake.gov/events/mah-jongg-mondays-23', '2026-11-12', 'ACTIVE')
