VALUES ('club_lenox-lenox-community-center-mah-jongg', 'Lenox Community Center Mah Jongg', 'lenox-lenox-community-center-mah-jongg', 'Town of Lenox community center; Bam Good Time listing says American Mahjong every Wednesday 10:30am-12:00pm, new players welcome. A search result for the town''s own pages also showed mah jongg in Room 109 (Mon beginner 10am-12pm, Wed, Fri) at $2/day ($1 members), but the town page itself could not be opened, so American / NMJL is unconfirmed from the venue.', (SELECT id FROM City WHERE name = 'Lenox' AND state = 'MA'), '65 Walker Street, Lenox, MA', 'https://www.townoflenox.com/node/13', '413-637-5530', NULL, NULL, NULL, 1, 0, 1, 1, 0, 0, NULL, 'Wednesdays 10:30am-12:00pm (per directory); town page snippet: Mon 10am-12pm beginner, Wed 6:30-9pm, Fri 1-3:30pm Room 109', 'https://bamgoodtime.com/clubs/listing/726c5a8b-9530-467d-a74c-7dc95d24fb3a', '2026-11-13', 'NEEDS_REVIEW')
