VALUES ('club_lenox-american-mahjong-retreat-at-canyon-ranch-lenox', 'American Mahjong Retreat at Canyon Ranch Lenox', 'lenox-american-mahjong-retreat-at-canyon-ranch-lenox', 'Canyon Ranch Lenox hosts Gold Coast Mahjong Club retreats. The Oct 26-28 2026 retreat page says: ''Beginners will receive a NMJL card and will have instructor support throughout the first few sessions of the retreat.'' Both 2026 American Mahjong retreats (Jul 12-14, Oct 26-28) are already past; the only listed upcoming mahjong retreat (Dec 19-21 2026, Lacey Schwartz) does not say American.', (SELECT id FROM City WHERE name = 'Lenox' AND state = 'MA'), 'Canyon Ranch, Lenox, MA', 'https://www.canyonranch.com/lenox/retreats/american-mahjong-retreat-oct-2026', NULL, NULL, NULL, NULL, 0, 1, 0, 1, 0, 0, NULL, 'Retreats; Oct 26-28 2026 from $1,750 per person per night (past)', 'https://www.canyonranch.com/lenox/retreats/american-mahjong-retreat-oct-2026', '2026-11-13', 'NEEDS_REVIEW')
