VALUES ('club_new-york-jcc-rockland-lewis-jcc-game-time', 'JCC Rockland (Lewis JCC) Game Time', 'new-york-jcc-rockland-lewis-jcc-game-time', 'Lewis JCC in West Nyack (Rockland County; NYC metro) lists daily Mah Jongg open play Mon-Fri 12-4pm (free for members) plus Beginner and Advanced Beginner Mahjong classes. The program page does not mention American / NMJL, so the variant is unconfirmed.', (SELECT id FROM City WHERE name = 'New York' AND state = 'NY'), '450 West Nyack Road, West Nyack, NY 10994', 'https://lewisjcc.org/game-time', NULL, NULL, NULL, NULL, 1, 1, 1, 1, 0, 0, NULL, 'Open Play Mon-Fri 12-4pm; Beginner Mahjong with Lisa Thursdays 10am-12pm (Nov 5-Dec 17 2026, no class Nov 26), members $160 / public $175 (price basis unclear)', 'https://lewisjcc.org/game-time', '2026-11-13', 'NEEDS_REVIEW')
