VALUES ('club_east-hills-sid-jacobson-jcc-mah-jongg', 'Sid Jacobson JCC Mah Jongg', 'east-hills-sid-jacobson-jcc-mah-jongg', 'Sid Jacobson JCC (East Hills, Long Island) runs 8-week Mah Jongg courses. Its own page says: "This eight-week course introduces beginners to Mah Jongg using official National Mah Jongg League rules" and "The 2026 National Mah Jongg League card ($15) must be purchased at the first class." Also offers a Thursday Mah Jongg Clinic for experienced players (drop-in possible). Fall 2026 sessions (Oct 13-Dec 14) already started; Tuesday class listed as full.', (SELECT id FROM City WHERE name = 'East Hills' AND state = 'NY'), '300 Forest Drive, East Hills, NY', 'https://www.sjjcc.org/programs/arts-culture/games/mah-jongg/', '516-484-1545', NULL, NULL, NULL, 1, 1, 0, 0, 0, 0, NULL, 'Fall 2026: Beginner Tue 7-9:30pm (Oct 13-Dec 8); Beginner Thu 4-6:30pm and Clinic Thu 10am-12:30pm (Oct 15-Dec 10); Beginner Mon 10am-12:30pm (Oct 19-Dec 14). Members $225 / nonmembers $300 per 8-week course.', 'https://www.sjjcc.org/programs/arts-culture/games/mah-jongg/beginner-mah-jongg-tuesday/', '2026-11-12', 'ACTIVE')
