VALUES ('club_charlotte-rack-n-roll-mah-jongg-open-play-in-the-qc', 'Rack ''n Roll - Mah Jongg Open Play in the QC', 'charlotte-rack-n-roll-mah-jongg-open-play-in-the-qc', 'Free American Mah Jongg open play run by the organizers on Meetup (Quail Corners / Providence Road area). Meetup group page: "We play by National Mah Jongg League rules - no blanks or table rules." Players need some prior American Mah Jongg lessons; the group does not offer new-learner classes. Advance signup required.', (SELECT id FROM City WHERE name = 'Charlotte' AND state = 'NC'), 'Harris Teeter, 1015 Providence Road, Charlotte, NC', 'https://www.meetup.com/racknrollmahjonggqc/', NULL, NULL, NULL, NULL, 0, 0, 1, 1, 0, 1, NULL, 'Monday evenings 6:00 PM (Meetup shows Mon Nov 16 6:00 PM at Harris Teeter); earlier sessions at Tap & Vine Quail Hollow, 8426 Park Road. Free; advance signup in Meetup required.', 'https://www.meetup.com/racknrollmahjonggqc/', '2026-11-13', 'ACTIVE')
